import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.StringTokenizer

class Solution {
    fun solve() {
        val n = readInt()
        val m = readInt()

        if (m == 1)
            write(n - 1)
        else
            write(1L * n * (m - 1))
    }

    companion object {
        lateinit var reader: BufferedReader
        lateinit var writer: PrintWriter

        @JvmStatic
        fun main(args: Array<String>) {
            reader = BufferedReader(InputStreamReader(System.`in`))
            writer = PrintWriter(System.out)

            try {
                Solution().solve()
            } catch (ex: Exception) {
                throw ex
            }

            reader.close()
            writer.close()
        }

        private var currentLineTokens: StringTokenizer = StringTokenizer("")

        fun readToken(): String {
            while (!currentLineTokens.hasMoreTokens()) {
                currentLineTokens = StringTokenizer(reader.readLine())
            }
            return currentLineTokens.nextToken()
        }

        fun readInt(): Int = readToken().toInt()
        fun readLong(): Long = readToken().toLong()
        fun readDouble(): Double = readToken().toDouble()

        fun readAndSplitLine(): Array<String> {
            return reader.readLine().trim().split(Regex("\\s+")).toTypedArray()
        }

        fun readIntArray(): IntArray = readAndSplitLine().map { it.toInt() }.toIntArray()
        fun readLongArray(): LongArray = readAndSplitLine().map { it.toLong() }.toLongArray()
        fun readDoubleArray(): DoubleArray = readAndSplitLine().map { it.toDouble() }.toDoubleArray()

        fun readIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = Array(numberOfRows) { IntArray(0) }
            for (i in 0 until numberOfRows) matrix[i] = readIntArray()
            return matrix
        }

        fun readAndTransposeIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = readIntMatrix(numberOfRows)
            val ret = Array(matrix[0].size) { IntArray(numberOfRows) }
            for (i in ret.indices) {
                for (j in 0 until numberOfRows) {
                    ret[i][j] = matrix[j][i]
                }
            }
            return ret
        }

        fun readLines(quantity: Int): Array<String> {
            val lines = Array(quantity) { "" }
            for (i in 0 until quantity) lines[i] = reader.readLine().trim()
            return lines
        }

        fun writeArray(array: Iterable<Any?>) {
            writer.println(array.joinToString(" "))
        }

        fun write(vararg array: Any?) {
            writeArray(array.toList())
        }

        fun <T> writeLines(array: Iterable<T>) {
            for (a in array) writer.println(a)
        }
    }
}

fun main(args: Array<String>) {
    Solution.main(args)
}
